//For Polymorphism:
class Base {
public:
  virtual void doSomething() = 0;
};

class Derived : public Base {
public:
  void doSomething() override { std::cout << "Derived"; }
};

SmartPtr<Base> spBase(new Derived());
spBase->doSomething(); // Calls Derived::doSomething() through polymorphism

code_example:
#include <iostream>
#include <memory>
class MyClass {
public:
  void print() { std::cout << "MyClass"; }
};
template <typename T>
class SmartPtr {
public:
  SmartPtr(T* ptr) : ptr_(ptr) {}
  ~SmartPtr() { delete ptr_; }
  T* operator->() const { return ptr_; }
private:
  T* ptr_;
};
int main() {
  SmartPtr<MyClass> sp(new MyClass());
  sp->print(); // Uses overloaded -> operator
  std::cout << std::endl;
  return 0;
}
